    @cached_property
    def _unwrapped_calls(self) -> List[Any]:
        if self.call is None:
            return [None]
        calls = []
        current = self.call
        while True:
            calls.append(current)
            unwrapped = inspect.unwrap(current)
            if unwrapped is not current:
                current = unwrapped
                continue
            if isinstance(current, partial):
                current = current.func
                continue
            break
        return calls
```

